/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.10);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.025);
  --radius: 6px;
  --radius-sm: 4px;
  --gutter: 20px;
  --pad: 20px;
  --transition: background-color 0.3s ease, color 0.3s ease;
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.12);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.01);
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}

/* ── Base ──
   Raster owns the page: paper background, ink text, and the visible
   204px module grid drawn behind everything. */
html{scroll-behavior:smooth;font-size:16px;overflow-x:clip}
body{
  overflow-x:clip;
  background-color:var(--bg);
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100vh;
  background-repeat:repeat-x;
  background-attachment:fixed;
  background-position:var(--grid-pos);
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.6;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps. */
.rs-t-xl{font-size:clamp(34px,5vw,52px);font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:38px;font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:22px;font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:17px;font-weight:500;letter-spacing:-.01em;line-height:1.5;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:15px;font-weight:500;letter-spacing:-.01em;line-height:1.6;color:var(--text);margin:0;text-wrap:pretty}
.rs-t-label{font-size:13px;font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* ── Reduced motion: nothing loops, nothing slides ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal{transition:none}
  .rs-subscribed{animation:none}
  .rs-theme-track,.rs-theme-sun,.rs-theme-moon{transition:none}
}
